// Compute a single _route token from the incoming Telegram update so the
// Switch node downstream can dispatch on one string instead of two distinct
// paths (message.text vs callback_query.data). Longer prefixes (tpp:) are
// checked before shorter ones (tp:) to avoid mis-routing. /learn uses a
// command-boundary regex (not startsWith) so /learning, /learn_more, etc.
// fall through to 'unknown' rather than being treated as /learn.
const LEARN_CMD = /^\/learn(?:@\w+)?(?:\s|$)/;
const items = $input.all();
return items.map((item) => {
  const m = item.json || {};
  const text = (m.message && m.message.text) || '';
  const data = (m.callback_query && m.callback_query.data) || '';
  let route = 'unknown';
  if (text === '/start') route = '/start';
  else if (LEARN_CMD.test(text)) route = '/learn';
  else if (text === '/quiz') route = '/quiz';
  else if (data.startsWith('qa:')) route = 'qa:';
  else if (data.startsWith('rs:')) route = 'rs:';
  else if (data.startsWith('tpp:')) route = 'tpp:';
  else if (data.startsWith('tp:')) route = 'tp:';
  else if (data.startsWith('qstart:')) route = 'qstart:';
  return { json: { ...m, _route: route } };
});

// Extract the URL argument from `/learn <url>` and normalise it for dedup.
// Regex-based parser mirrors task-3/lib/urlNormalizer.js verbatim — the
// WHATWG `URL` constructor is not exposed inside the n8n Code-node task-runner
// sandbox on n8n Cloud, so a `new URL(...)`-based version silently fell
// through to the error branch.
// Rules: scheme must be http/https; host lowercased; fragment dropped;
// trailing slash on non-root paths dropped; query preserved verbatim.
// On invalid input emit one item with valid=false plus _error.code so the
// downstream Switch routes to the unified error builder.
const URL_RE = /^(https?):\/\/([^\s/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i;
const AUTHORITY_RE = /^([^:]+)(?::(\d+))?$/;
function normalizeUrl(raw) {
  if (typeof raw !== 'string') return null;
  const t = raw.trim();
  if (t === '') return null;
  const m = t.match(URL_RE);
  if (!m) return null;
  const auth = m[2].match(AUTHORITY_RE);
  if (!auth || !auth[1]) return null;
  const protocol = m[1].toLowerCase() + ':';
  const host = auth[1].toLowerCase();
  const port = auth[2] ? `:${auth[2]}` : '';
  let path = m[3] || '/';
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  const search = m[4] || '';
  return `${protocol}//${host}${port}${path}${search}`;
}

const items = $input.all();
return items.map((item) => {
  const m = item.json || {};
  const text = (m.message && m.message.text) || '';
  const chatId = String((m.message && m.message.chat && m.message.chat.id) || '');
  const match = text.match(/^\/learn(?:@\w+)?(?:\s+(.*))?$/);
  const originalUrl = match && match[1] ? match[1].trim() : '';
  const normalizedUrl = normalizeUrl(originalUrl);
  const valid = !!(chatId && normalizedUrl);
  const code = originalUrl === '' ? 'no_url' : 'invalid_url';
  return {
    json: {
      ...m,
      _learn: {
        chatId,
        originalUrl,
        normalizedUrl: normalizedUrl || '',
        valid,
        reason: valid ? null : code,
        _error: valid ? null : { code },
      },
    },
  };
});

// Second Teacher attempt: same parse contract as the first, but a final
// failure here surfaces a user-visible error (PRD #7 / #8) instead of
// triggering another retry. Carries both raw responses + structured errors
// in _learn for post-mortem visibility in the n8n execution log.
const DIFFICULTY = new Set(['beginner', 'intermediate', 'advanced']);
function isNonEmptyString(v) { return typeof v === 'string' && v.trim().length > 0; }
function isStrArr(v, min, max) {
  if (!Array.isArray(v)) return false;
  if (v.length < min || v.length > max) return false;
  return v.every(isNonEmptyString);
}
function parseTeacher(raw) {
  let p;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { return { ok: false, error: { code: 'not_json', message: 'Teacher output is not valid JSON' } }; }
  if (p === null || typeof p !== 'object' || Array.isArray(p)) return { ok: false, error: { code: 'not_object', message: 'Teacher output is not a JSON object' } };
  if (!isNonEmptyString(p.title)) return { ok: false, error: { code: 'schema', message: 'title is missing or empty' } };
  if (!isStrArr(p.mainConcepts, 3, 5)) return { ok: false, error: { code: 'schema', message: 'mainConcepts must be an array of 3..5 non-empty strings' } };
  if (!isStrArr(p.keyPoints, 5, 7)) return { ok: false, error: { code: 'schema', message: 'keyPoints must be an array of 5..7 non-empty strings' } };
  if (!DIFFICULTY.has(p.difficulty)) return { ok: false, error: { code: 'schema', message: 'difficulty must be beginner | intermediate | advanced' } };
  return { ok: true, value: { title: p.title.trim(), mainConcepts: p.mainConcepts.map((s) => s.trim()), keyPoints: p.keyPoints.map((s) => s.trim()), difficulty: p.difficulty } };
}
function mintShortId(seed) {
  const s = seed === null || seed === undefined ? '' : String(seed);
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(36).padStart(8, '0').slice(0, 8);
}

const learnCtx = $('/learn extract content').first().json._learn;
const firstFail = $('/learn Teacher parse').first().json._learn || {};
const chainItem = $input.first().json;
const rawText = (typeof chainItem.text === 'string' ? chainItem.text : (typeof chainItem.output === 'string' ? chainItem.output : JSON.stringify(chainItem)));
const result = parseTeacher(rawText);
if (!result.ok) {
  return [{
    json: {
      _learn: {
        ...learnCtx,
        _error: { code: 'teacher_failed' },
        _teacherErrorFirst: firstFail._teacherError || null,
        _teacherErrorSecond: result.error,
        _teacherRawFirst: firstFail._teacherRawFirst || null,
        _teacherRawSecond: rawText,
      },
    },
  }];
}
const summary = result.value;
const shortId = mintShortId(`${learnCtx.chatId}|${learnCtx.normalizedUrl}`);
return [{
  json: {
    _learn: {
      ...learnCtx,
      cached: true,
      shortId,
      summary,
    },
  },
}];

// Unified error-message builder for /learn failures (PRD error table
// rows #1, #2, #3, #4, #5, #7, #8). The error code is set by whichever
// upstream Code node detected the failure and routed here via a Switch.
// Telegram parse_mode is HTML — pure dynamic fields are escaped, static
// markup (<code> ... </code>) is interpolated verbatim.
function htmlEscape(v) {
  if (v === null || v === undefined) return '';
  const s = typeof v === 'string' ? v : String(v);
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const items = $input.all();
return items.map((item) => {
  const learn = (item.json && item.json._learn) || {};
  const chatId = learn.chatId;
  const err = learn._error || { code: 'unknown' };
  let html;
  switch (err.code) {
    case 'no_url':
    case 'invalid_url':
      html = 'Send a URL after /learn, e.g. <code>/learn https://example.com/article</code>';
      break;
    case 'jina_4xx':
    case 'jina_5xx':
      html = `I couldn\u2019t fetch that page (status ${htmlEscape(err.status)}). Try a different URL?`;
      break;
    case 'jina_network':
      html = 'I couldn\u2019t fetch that page (network error). Try a different URL?';
      break;
    case 'too_short':
      html = 'That page doesn\u2019t have enough content for me to summarize. Try a different URL?';
      break;
    case 'teacher_failed':
      html = 'Sorry, I had trouble processing this one. Try /learn again, or pick a different URL?';
      break;
    default:
      html = 'Something went wrong. Try again?';
  }
  return { json: { _render: { chatId, html }, _learn: learn } };
});

// Decide whether the upstream Data Table `get` returned an existing row.
// Forward the original `_learn` context (read from the parse node) plus
// either the cached row (hit) or just the chatId+url (miss).
const learnCtx = $('/learn parse + normalize').first().json._learn;
const rows = $input.all().map((it) => it.json).filter((r) => r && r.short_id);
if (rows.length > 0) {
  const r = rows[0];
  let mainConcepts = [];
  let keyPoints = [];
  try { mainConcepts = JSON.parse(r.main_concepts || '[]'); } catch { mainConcepts = []; }
  try { keyPoints = JSON.parse(r.key_points || '[]'); } catch { keyPoints = []; }
  return [{
    json: {
      _learn: {
        ...learnCtx,
        cached: true,
        shortId: r.short_id,
        summary: {
          title: r.title,
          mainConcepts,
          keyPoints,
          difficulty: r.difficulty,
        },
      },
    },
  }];
}
return [{
  json: {
    _learn: { ...learnCtx, cached: false },
  },
}];

// Classify the Jina response and prepare extracted content.
// Three concerns merged here to keep the topology flat (PRD error rules #3, #4, #5, #6):
//   1. Status check — HTTP node runs with neverError+fullResponse, so 4xx/5xx land here
//      with a numeric statusCode. Timeouts / network errors arrive via the error
//      output (onError=continueErrorOutput) and lack statusCode entirely.
//   2. Length floor — under 500 chars (post-trim) → too_short error.
//   3. Token budget — over ~30k tokens (≈120k chars) → silent head-truncate.
// Emits _learn with either _error set (failure paths) or extractedContent set (happy path).
const MAX_CHARS = 120000;
const MIN_CHARS = 500;
const learnCtx = $('/learn parse + normalize').first().json._learn;
const item = $input.first().json || {};

if (typeof item.statusCode !== 'number') {
  return [{ json: { _learn: { ...learnCtx, _error: { code: 'jina_network' } } } }];
}
const status = item.statusCode;
if (status >= 400) {
  const code = status >= 500 ? 'jina_5xx' : 'jina_4xx';
  return [{ json: { _learn: { ...learnCtx, _error: { code, status } } } }];
}

// 2xx — body is a string under responseFormat=text + fullResponse=true.
let raw = '';
if (typeof item.body === 'string') raw = item.body;
else if (typeof item.data === 'string') raw = item.data;
else if (typeof item === 'string') raw = item;
else raw = JSON.stringify(item.body || item);

const trimmedLen = raw.trim().length;
if (trimmedLen < MIN_CHARS) {
  return [{ json: { _learn: { ...learnCtx, _error: { code: 'too_short', charCount: trimmedLen } } } }];
}

const truncated = raw.length > MAX_CHARS ? raw.slice(0, MAX_CHARS) : raw;
return [{
  json: {
    _learn: {
      ...learnCtx,
      extractedContent: truncated,
      originalLength: raw.length,
      truncated: raw.length > MAX_CHARS,
      truncatedLength: truncated.length,
    },
  },
}];

// Validate the first Teacher response into the Summary shape.
// Mirrors task-3/lib/teacherOutputParser.js — same { code, message } error
// shape so the lib unit tests document the contract that the workflow runs.
// On failure emits _learn with _teacherFailed=true (carrying the raw response
// and structured parse error) so the downstream Switch routes to the retry
// sub-flow. On success emits _learn with the parsed Summary plus shortId.
const DIFFICULTY = new Set(['beginner', 'intermediate', 'advanced']);
function isNonEmptyString(v) { return typeof v === 'string' && v.trim().length > 0; }
function isStrArr(v, min, max) {
  if (!Array.isArray(v)) return false;
  if (v.length < min || v.length > max) return false;
  return v.every(isNonEmptyString);
}
function parseTeacher(raw) {
  let p;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { return { ok: false, error: { code: 'not_json', message: 'Teacher output is not valid JSON' } }; }
  if (p === null || typeof p !== 'object' || Array.isArray(p)) return { ok: false, error: { code: 'not_object', message: 'Teacher output is not a JSON object' } };
  if (!isNonEmptyString(p.title)) return { ok: false, error: { code: 'schema', message: 'title is missing or empty' } };
  if (!isStrArr(p.mainConcepts, 3, 5)) return { ok: false, error: { code: 'schema', message: 'mainConcepts must be an array of 3..5 non-empty strings' } };
  if (!isStrArr(p.keyPoints, 5, 7)) return { ok: false, error: { code: 'schema', message: 'keyPoints must be an array of 5..7 non-empty strings' } };
  if (!DIFFICULTY.has(p.difficulty)) return { ok: false, error: { code: 'schema', message: 'difficulty must be beginner | intermediate | advanced' } };
  return { ok: true, value: { title: p.title.trim(), mainConcepts: p.mainConcepts.map((s) => s.trim()), keyPoints: p.keyPoints.map((s) => s.trim()), difficulty: p.difficulty } };
}

// djb2 hash for the deterministic 8-char short_id.
function mintShortId(seed) {
  const s = seed === null || seed === undefined ? '' : String(seed);
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(36).padStart(8, '0').slice(0, 8);
}

const learnCtx = $('/learn extract content').first().json._learn;
const chainItem = $input.first().json;
const rawText = (typeof chainItem.text === 'string' ? chainItem.text : (typeof chainItem.output === 'string' ? chainItem.output : JSON.stringify(chainItem)));
const result = parseTeacher(rawText);
if (!result.ok) {
  // Forward extractedContent so the retry prompt Set node can re-interpolate it,
  // and the raw response for logging (PRD error rules #7/#8).
  return [{
    json: {
      _learn: {
        ...learnCtx,
        _teacherFailed: true,
        _teacherError: result.error,
        _teacherRawFirst: rawText,
      },
    },
  }];
}
const summary = result.value;
const shortId = mintShortId(`${learnCtx.chatId}|${learnCtx.normalizedUrl}`);
return [{
  json: {
    _learn: {
      ...learnCtx,
      cached: true,
      shortId,
      summary,
    },
  },
}];

// The Data Table insert node emits the inserted row's columns; we don't
// need them — we already carry the Summary in our context. Re-emit the
// _learn context from whichever Teacher parse actually produced the Summary
// (retry parse if the first attempt failed; original parse otherwise).
// Reading the original parse unconditionally — as the slice-3 first cut did —
// would render the FAILED first-attempt context on retry-success and ship a
// blank/garbled summary while the Data Table row was correct (S3-HIGH-002).
function pick(nodeName) {
  try {
    const item = $(nodeName).first();
    if (item && item.json && item.json._learn && item.json._learn.summary) {
      return item.json._learn;
    }
  } catch (_) { /* node didn't run on this branch */ }
  return null;
}
const learnCtx = pick('/learn Teacher retry parse') || pick('/learn Teacher parse') || {};
return [{ json: { _learn: learnCtx } }];

// Render the Summary into the Telegram HTML body + inline keyboard.
// Mirrors task-3/lib/summaryRenderer.js. Every dynamic field is routed
// through htmlEscape; static markup (`<b>`, newlines, emojis) is verbatim.
function htmlEscape(v) {
  if (v === null || v === undefined) return '';
  const s = typeof v === 'string' ? v : String(v);
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const BADGES = { beginner: '🟢', intermediate: '🟡', advanced: '🔴' };
const items = $input.all();
return items.map((item) => {
  const c = (item.json && item.json._learn) || {};
  const summary = c.summary || {};
  const shortId = c.shortId || '';
  const badge = BADGES[summary.difficulty] || '⚪';
  const known = badge !== '⚪';
  const label = known ? summary.difficulty.charAt(0).toUpperCase() + summary.difficulty.slice(1) : 'Unknown';
  const titleHtml = htmlEscape(summary.title);
  const conceptsHtml = (summary.mainConcepts || []).map((x) => `• ${htmlEscape(x)}`).join('\n');
  const pointsHtml = (summary.keyPoints || []).map((x) => `• ${htmlEscape(x)}`).join('\n');
  const html = [
    `<b>${titleHtml}</b>`,
    `${badge} <b>Difficulty:</b> ${htmlEscape(label)}`,
    '',
    '<b>Main concepts</b>',
    conceptsHtml,
    '',
    '<b>Key points</b>',
    pointsHtml,
  ].join('\n');
  return {
    json: {
      _learn: c,
      _render: {
        chatId: c.chatId,
        html,
        callbackData: `qstart:${shortId}`,
      },
    },
  };
});

// Build the topic picker for /quiz. Mirrors task-3/lib/topicPickerBuilder.js.
// Body is a numbered list of materials; keyboard is a STATIC 3-row layout
// (2 grid rows of 4 numbered buttons + 1 pagination row of 3 buttons). This
// shape is dictated by an n8n platform constraint discovered in slice 4:
// the Telegram node v1.2 inlineKeyboard.rows fixedCollection is
// statically-sized at design time, so the only way to render with a fixed
// node config is to pre-declare exactly 3 rows whose per-cell values are
// expression-driven. Dynamic-length keyboards would need an HTTP Request
// to the Bot API with the token in the URL via $vars/$env — not available
// on the user's n8n Cloud plan.
function htmlEscape(v) {
  if (v === null || v === undefined) return '';
  const s = typeof v === 'string' ? v : String(v);
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const DIFFICULTY_EMOJI = { beginner: '🟢', intermediate: '🟡', advanced: '🔴' };
const PAGE_SIZE = 8;
const GRID_SIZE = 8;
const HEADER = '<b>📚 Pick a material to quiz on:</b>';
const PREV = '⬅️ Prev';
const NEXT = 'Next ➡️';
const NOOP_TEXT = '⠀';
const EMPTY_HTML = "You haven't saved any materials yet. Send /learn &lt;URL&gt; to add one.";

const trigger = $('Telegram Trigger').first().json;
const chatId = String((trigger.message && trigger.message.chat && trigger.message.chat.id) || '');
const materials = $input.all().map((it) => it.json).filter((r) => r && r.short_id);

if (materials.length === 0) {
  // Empty-state branch: routed to a separate Telegram node that omits the keyboard.
  return [{ json: { _picker: { chatId, empty: true, hasKeyboard: false, html: EMPTY_HTML, gridButtons: null, paginationButtons: null, page: 0, totalPages: 0 } } }];
}

const page = 0;
const totalPages = Math.max(1, Math.ceil(materials.length / PAGE_SIZE));
const slice = materials.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
const lines = slice.map((m, i) => {
  const emoji = DIFFICULTY_EMOJI[m.difficulty] || '⚪';
  const title = m.title == null ? '' : String(m.title);
  return `${i + 1}. ${emoji} ${htmlEscape(title)}`;
});
const pageLine = totalPages > 1 ? `\n<i>Page ${page + 1} of ${totalPages}</i>` : '';
const html = `${HEADER}${pageLine}\n\n${lines.join('\n')}`;
const noopCb = `tpp:${page}`;
const gridButtons = [];
for (let i = 0; i < GRID_SIZE; i++) {
  if (i < slice.length) gridButtons.push({ text: String(i + 1), callback_data: `tp:${slice[i].short_id}` });
  else gridButtons.push({ text: NOOP_TEXT, callback_data: noopCb });
}
const prevPage = totalPages > 1 ? (page > 0 ? page - 1 : totalPages - 1) : page;
const nextPage = totalPages > 1 ? (page < totalPages - 1 ? page + 1 : 0) : page;
const paginationButtons = [
  { text: totalPages > 1 ? PREV : NOOP_TEXT, callback_data: `tpp:${prevPage}` },
  { text: `Page ${page + 1}/${totalPages}`, callback_data: `tpp:${page}` },
  { text: totalPages > 1 ? NEXT : NOOP_TEXT, callback_data: `tpp:${nextPage}` },
];
return [{ json: { _picker: { chatId, empty: false, hasKeyboard: true, html, gridButtons, paginationButtons, page, totalPages } } }];

// Decode tpp:{pageIdx} and capture every field the picker rebuild + the
// in-place message edit need. The picker we will edit IS the message
// hosting the tapped button — its chat_id and message_id are right in the
// callback_query payload. Non-numeric / negative pageIdx silently snaps to 0;
// the downstream picker builder additionally clamps to a valid page.
const items = $input.all();
return items.map((item) => {
  const m = item.json || {};
  const cq = m.callback_query || {};
  const msg = cq.message || {};
  const chatId = String((msg.chat && msg.chat.id) || '');
  const messageId = msg.message_id != null ? msg.message_id : null;
  const queryId = String(cq.id || '');
  const data = String(cq.data || '');
  let pageIdx = 0;
  if (data.startsWith('tpp:')) {
    const rest = data.slice(4);
    if (/^\d+$/.test(rest)) pageIdx = Number(rest);
  }
  return { json: { _tpp: { chatId, messageId, queryId, pageIdx } } };
});

// Rebuild the topic picker for the requested page using the same numbered-
// grid layout as /quiz build picker. Reads page from the parse node's
// _tpp.pageIdx, threads chatId / messageId / queryId through for the
// downstream edit, and clamps out-of-range pageIdx silently. See the head
// comment on /quiz build picker for why the keyboard layout is static.
function htmlEscape(v) {
  if (v === null || v === undefined) return '';
  const s = typeof v === 'string' ? v : String(v);
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const DIFFICULTY_EMOJI = { beginner: '🟢', intermediate: '🟡', advanced: '🔴' };
const PAGE_SIZE = 8;
const GRID_SIZE = 8;
const HEADER = '<b>📚 Pick a material to quiz on:</b>';
const PREV = '⬅️ Prev';
const NEXT = 'Next ➡️';
const NOOP_TEXT = '⠀';
const EMPTY_HTML = "You haven't saved any materials yet. Send /learn &lt;URL&gt; to add one.";

const ctx = $('tpp: parse').first().json._tpp;
const { chatId, messageId, queryId, pageIdx } = ctx;
const materials = $input.all().map((it) => it.json).filter((r) => r && r.short_id);

if (materials.length === 0) {
  return [{ json: { _picker: { chatId, messageId, queryId, empty: true, hasKeyboard: false, html: EMPTY_HTML, gridButtons: null, paginationButtons: null, page: 0, totalPages: 0 } } }];
}

const totalPages = Math.max(1, Math.ceil(materials.length / PAGE_SIZE));
const safePage = Math.min(Math.max(0, pageIdx | 0), totalPages - 1);
const slice = materials.slice(safePage * PAGE_SIZE, (safePage + 1) * PAGE_SIZE);
const lines = slice.map((m, i) => {
  const emoji = DIFFICULTY_EMOJI[m.difficulty] || '⚪';
  const title = m.title == null ? '' : String(m.title);
  return `${i + 1}. ${emoji} ${htmlEscape(title)}`;
});
const pageLine = totalPages > 1 ? `\n<i>Page ${safePage + 1} of ${totalPages}</i>` : '';
const html = `${HEADER}${pageLine}\n\n${lines.join('\n')}`;
const noopCb = `tpp:${safePage}`;
const gridButtons = [];
for (let i = 0; i < GRID_SIZE; i++) {
  if (i < slice.length) gridButtons.push({ text: String(i + 1), callback_data: `tp:${slice[i].short_id}` });
  else gridButtons.push({ text: NOOP_TEXT, callback_data: noopCb });
}
const prevPage = totalPages > 1 ? (safePage > 0 ? safePage - 1 : totalPages - 1) : safePage;
const nextPage = totalPages > 1 ? (safePage < totalPages - 1 ? safePage + 1 : 0) : safePage;
const paginationButtons = [
  { text: totalPages > 1 ? PREV : NOOP_TEXT, callback_data: `tpp:${prevPage}` },
  { text: `Page ${safePage + 1}/${totalPages}`, callback_data: `tpp:${safePage}` },
  { text: totalPages > 1 ? NEXT : NOOP_TEXT, callback_data: `tpp:${nextPage}` },
];
return [{ json: { _picker: { chatId, messageId, queryId, empty: false, hasKeyboard: true, html, gridButtons, paginationButtons, page: safePage, totalPages } } }];

// Decode tp:{materialShortId}. The picker message hosting the tapped button
// is the callback_query.message — we capture its id so the qgen branch can
